.sessions__panel .srow--done .srow__name{color:var(--tx-ink-2)}
.sessions__panel .srow--noshow .srow__name{
  color:var(--tx-ink-3);text-decoration:line-through}
.sessions__panel .srow--done .srow__state{color:var(--tx-ok)}
.sessions__panel .srow--noshow .srow__state{color:var(--tx-danger)}

/* Child elements — no scoping needed, Today uses different names (.srow__t/.srow__b) */
.srow__body{display:flex;flex-direction:column;gap:3px;min-width:0}
.srow__name{
  font-size:14.5px;font-weight:500;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.srow__plan{font-size:12.5px;color:var(--tx-ink-3)}
.srow__meta{display:flex;flex-direction:column;align-items:flex-end;gap:3px}
