.srow__tag--remote{color:var(--tx-accent);background:var(--tx-accent-soft)}
.srow__tag--floor{color:var(--tx-ink-3);background:var(--tx-surface-2)}
.srow__tag--log{color:var(--tx-ok);background:var(--tx-ok-soft)}
.srow__state{
  display:flex;align-items:center;justify-content:center;
